#include "stdafx.h"

// =============================================================================
//  (th4) TURKISH localization (LANG_TR). Mirrors LocalizationDE.cpp structure.
//
//  ENCODING: raw CP1254 bytes (latin-1 on disk). CP1254 is CP1252 with six
//  positions reassigned:
//        0xD0 G-breve   0xDD I-dot     0xDE S-cedilla
//        0xF0 g-breve   0xFD dotless-i 0xFE s-cedilla
//  Every other Turkish letter that needs a glyph -- C-cedilla 0xC7, O-diaeresis
//  0xD6, U-diaeresis 0xDC and their lowercase partners -- sits at the SAME byte
//  in CP1252, so the Portuguese/French CEL font pack already draws it correctly.
//
//  GLYPH STATE: the three Turkish-only letters currently FOLD to G / I / S,
//  because the PT CEL frames they would otherwise land on hold Eth, Y-acute and
//  Thorn -- i.e. the WRONG letters. Folding is always readable; drawing Thorn
//  where an S-cedilla belongs is not. Write the real CP1254 bytes anyway: when
//  TH4loc_tur.mor ships the three repainted frames, the six table entries flip
//  and every string in this file starts rendering with full diacritics, with no
//  text changes. See TR_GLYPH_FLIP in dataseg.cpp.
//
//  DOTLESS I: Turkish distinguishes i/I-dot from dotless-i/I. The CEL fonts are
//  caps-only, so plain ASCII 'i' renders as 'I'. Where the distinction matters
//  visually, write the explicit CP1254 byte rather than relying on ASCII 'i'.
//
//  ---- STATUS -------------------------------------------------------------
//  Batch: SPEECH -- Deckard Cain only (34 rows). Every other table still holds a
//  lone placeholder => 0 rows => those fall back to English. Storage is RAW
//  CP1254 bytes, as German/Portuguese do.
//  (was) SCAFFOLD ONLY. Every table holds a lone placeholder => 0 rows => the whole
//  UI falls back to English. This is a valid, shippable state: selecting
//  language 10 gives a working English build with the Turkish font path active.
//  Fill tables in batches; keys must byte-exactly match the English source
//  literal or the row is silently ignored.
// =============================================================================

struct UiStr  { const char* en; const char* tr; }; // .tr column holds the TR text
struct IdxStr { int index; const char* tr; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

