// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* TR_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(TR_Ui);           return TR_Ui;
		case OVL_MENU:          *n = countRows(TR_Menu);         return TR_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(TR_UniqueItem);   return TR_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(TR_AffixPrefix);  return TR_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(TR_AffixSuffix);  return TR_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(TR_BaseItem);     return TR_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(TR_BaseName2);    return TR_BaseName2;
		case OVL_ELEMENT:       *n = countRows(TR_Element);      return TR_Element;
		case OVL_SPICIES:       *n = countRows(TR_Spicies);      return TR_Spicies;
		case OVL_ICEAGE:        *n = countRows(TR_IceAge);       return TR_IceAge;
		case OVL_SPELL:         *n = countRows(TR_Spell);        return TR_Spell;
		case OVL_SPELL_NOM:     *n = countRows(TR_SpellNom);     return TR_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(TR_PerkName);     return TR_PerkName;
		case OVL_PERK_DESC:     *n = countRows(TR_PerkDesc);     return TR_PerkDesc;
		case OVL_WARP:          *n = countRows(TR_Warp);         return TR_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* TR_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(TR_Speech);     return TR_Speech;
		case OVL_ONSCREEN:  *n = countRows(TR_OnScreen);   return TR_OnScreen;
		case OVL_QUEST:     *n = countRows(TR_Quest);      return TR_Quest;
	}
	*n = 0; return 0;
}


