//  (th4) Game Changer info panel. Reached via LocalizedGCInfoName/Desc.
//  Layout mirrors the English GC_Names_InfoWindow / GC_Descriptions_InfoWindow in
//  GameChangers.cpp: "Name\n\n\nCategory\n\nBody". The \n counts carry the panel
//  layout, so they must match exactly.
// -----------------------------------------------------------------------------
const char* TR_GCInfoName( int gc )
{
	switch( gc ){
		case 0: return "None (skiped)";
		case 1: return "Otomatik kayit";
		case 2: return "Bagli Teçhizat";
		case 3: return "Esya Düsüsü";
		case 4: return "Zahmetsiz";
		case 5: return "Kendi Yagiyla Kavrul";
		case 6: return "Imkânsiz";
		case 7: return "Yasak";
		case 8: return "Tam Temas";
		case 9: return "Gece Soyu";
		case 10: return "Kes Biç";
		case 11: return "Asili";
		case 12: return "Bu Benim Sirrim";
		case 13: return "Yenilenme yok";
		case 14: return "Temiz Eller";
		case 15: return "Buz Çagi";
		case 16: return "Bugün de Ayni Gün";
		case 17: return "Daha Sert Canavarlar";
		case 18: return "Yok Olmaz Esyalar";
		case 19: return "Harita Yok";
		case 20: return "Çifte Hasar";
		case 21: return "Kötülügü Görme";
		case 22: return "Kara Ölüm";
		case 23: return "Kör Talih";
		case 24: return "Acimasiz Demir";
		case 25: return "Hizlanma";
		case 26: return "Çilecilik";
		case 27: return "Terminatör";
		case 28: return "Süper Mutant";
		case 29: return "Enclave Askeri";
	}
	return 0;
}

const char* TR_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "None (skiped)";
		case 1: return "Otomatik kayit\n\n\nOynanisi degistirir\n\nOyuncunun oyunu elle kaydetme zorunlulugunu ortadan kaldirir; kayit, tipki çok oyunculu moddaki gibi kendiliginden yapilir.";
		case 2: return "Bagli Teçhizat\n\n\nZorluk katar\n\nSavas sirasinda esya kusanmayi ya da çikarmayi imkânsiz kilar (el yuvalari hariç).";
		case 3: return "Esya Düsüsü\n\n\nZorluk katar\n\nÖlmek, kusandigin esyalari düsürmene yol açar.\n\nUyari: düsen esyalar ayni oyun oturumunda alinmazsa yok olurlar.";
		case 4: return "Zahmetsiz\n\n\nOyunu kolaylastirir\n\nCanavarlar sana yalnizca yarim hasar verir.\nBundan kolayi yok.";
		case 5: return "Kendi Yagiyla Kavrul\n\n\nZorluk katar\n\nKasabalilar sana hiçbir esya satmaz.\n\nYine de hizmetlerini sunmayi sürdürürler: dedikodu, görev diyaloglari, onarim, tanimlama, büyüleme, zanaat, yuva açma, sarj.";
		case 6: return "Imkânsiz\n\n\nOyunu zorlastirir\n\nCanavarlar sana çifte hasar verir.\nBundan zoru yok.";
		case 7: return "Yasak\n\n\nZorluk katar\n\nCanavarlar artik rastgele nitelik iksiri düsürmez\nNot: Agir Içici avantaji benzersiz canavarlardan iksir vermeye devam eder";
		case 8: return "Tam Temas\n\n\nOyunu kolaylastirir\n\nMenzilli saldirisi olan canavarlar geri çekilmez.";
		case 9: return "Gece Soyu\n\n\nSeni bir vampir yapar\n\nKanla yasar, kanla ölürsün. açligin doymak bilmez, ama zayiflari avlamak için gereken her seye sahipsin\n\nBu, oynanisi degistirir.\nEsya kullanmaz, dogustan gelen güçlerine dayanirsin.";
		case 10: return "Kes Biç\n\n\nOyunu kolaylastirir\n\nCanavar türüne göre silah türünü (kesici ya da künt) degistirmek zorunda degilsin artik. Tüm silahlar tüm canavar türlerine standart hasar verir.";
		case 11: return "Asili\n\n\nOyunu kolaylastirir\n\nCanavarlar tüm bagisikliklarini yitirir ve büyü degistirmeye gerek kalmaz -- her tür büyü ise yarar.\nTas Laneti, Kemik Ruhu, Element ve Kutsal büyüler bundan etkilenmez.";
		case 12: return "Bu Benim Sirrim\n\n\nOyunu kolaylastirir\n\nHiddet'in bekleme süresi yoktur ve biter bitmez yeniden kullanilabilir.";
		case 13: return "Yenilenme Yok\n\n\nZorluk katar\n\nKarakterin temel can ve mana yenilenmesi yoktur.";
		case 14: return "Temiz Eller\n\n\nZorluk katar\n\nCanavarlar karakterin kusanabilecegi esyalari düsürmez.\nOyuncunun bunlari satin alarak ve/veya büyüleyerek edinmesi beklenir.";
		case 15: return "Buz Çagi\n\n\nGörsel degisiklik\n\nZindan katlari derin bir kis ortasindaymis gibi görünür, her yer buz tutmustur.\nCehennem donsaydi nasil görünürdü, hiç düsündün mü?";
		case 16: return "Bugün de Ayni Gün\n\n\nOynanisi degistirir\n\nHer seferinde ayni zindan, ayni canavarlarla üretilir. Her oynayista zamanlamani gelistirebilirsin.";
		case 17: return "Daha Sert Canavarlar\n\n\nOyunu zorlastirir\n\nCanavarlarin +%200 can puani olur.";
		case 18: return "Yok Olmaz Esyalar\n\n\nOyunu kolaylastirir\n\nDayaniklilik sifira düsse bile esyalar yok olmaz. Bunun yerine onarilana dek kullanilamaz hâle gelir.";
		case 19: return "Harita Yok\n\n\nZorluk katar\n\nOtomatik harita kullanilamaz\nZindanlarda yolunu ona güvenmeden bulmak zorundasin\n\nSimdiden kayboldun mu?";
		case 20: return "Çifte Hasar\n\n\nOyunu kolaylastirir\n\nSaldirilarin canavarlara çifte hasar verir\n\nUyari: hayal kirikligi yaratacak kadar kolaylasabilir.\nSavasin heyecanini korumak istiyorsan bunu seçme.";
		case 21: return "Kötülügü Görme\n\n\nZorluk katar\n\nGörme, karanliktaki canavarlari belirginlestirmez.";
		case 22: return "Kara Ölüm\n\n\nEnfekte oldun\n\nKara Ölüm salgini seni ele geçirdi. Yavas yavas, sonunda kaçinilmaz olarak seni öldürecek olumsuz belirtiler gelistirecek.\n\nOnu tedavi edemezsin, iyilestiremezsin ve durduramazsin. Zamanla gitgide agirlasacak. Bu ölümcül hastaliktan kaçis yok.";
		case 23: return "Kör Talih\n\n\nZorluk katar\n\nSans er ya da geç tükenir. Seninki hiç baslamadi bile.\n\nOyuna tüm nitelikler 5 ile basla. Seviye atlayinca yalnizca 2 nitelik puani al. Büyü bulma becerileri, kazanilan tecrübe ve altin bulma yetisi %75 azalir. Oyuna hiçbir esya olmadan basla.\n\nTecrübe, iksir düsüsü, büyülü esya bulma ve seviye nitelikleri konusunda sana yardim edecek avantaj yok.";
		case 24: return "Acimasiz Demir\n\n\nZorluk katar\n\nKlasik Diablo Ironman farkliydi.\n\nSeviye basina nitelik artisi, ek tecrübe, patronlardan yag ve tanimlama yoktu. Büyü bulmada da iyilestirme yoktu.\n\nBu OD seni o köklere döndürür.";
		case 25: return "Hizlanma\n\n\nOyunu kolaylastirir\n\nTecrübe 2 katina çikar.";
		case 26: return "Çilecilik\n\n\nZorluk katar\n\nOyun kendiliginden kaydedilir.\n\nÖlünce esyalar düser. Kasabada dirilemezsin (yeni oyun açman gerekir) ve bu yüzden düsen tüm esyalar kaybolur.\n\nHardcore mod gibidir, ama karakterini yitirmek yerine kusandigin esyalari yitirirsin.";
		case 27: return "Terminatör\n\n\nSen bir Cyberdyne Systems seri birimisin. Model 101, sizma. CPU okuma-yazma kipi etkin. Görevi yerine getirmek için geçmise gönderildin.\n\nAna hedef: Uber Diablo.\n\nIkincil hedef: canavarlari yok et.\n\nKosul: yerli özneler için insan görünmek.\n\nTemel yükseltmeler kuruldu. Kendi kendine ögrenme yoluyla ek yükseltmeler mevcut.";
		case 28: return "Süper Mutant\n\n\nGövden, siradan bir adami ikiye bölecek silahlari tasiyabilir.\n\nMiniguns.\n\nBu dünyada var olmamasi gereken seyler. Artik büyü yapmiyorsun. Buna ihtiyacin yok.\n\nTetigi çektiginde yaylim atesi cehennem zebanilerini firtinadaki kâgit gibi paramparça eder.";
		case 29: return "Enclave Askeri\n\n\nMutantlari ve genetik safsizligi yok etmek için egitilmis bir Enclave Silahli Kuvvetleri askeri.\n\nKendini nükleer atesi hiç tanimamis, ama baska türden bir pisligi olan bir dünyada mahsur bulur -- Cehennem zebanileri.\n\nDüsman degisti. Amaç degismedi.\n\nYetenekler: Enerji silahlari kullanir ve dövüs dronlari konuslandirir. Element savasinda usta.";
	}
	return 0;
}


